    public void Update(EnemyAI ai)
    {
        ai.transform.Rotate(0f, 30f * Time.deltaTime, 0f);
        float dist = Vector3.Distance(ai.transform.position, ai.Player.position);
        if (dist < 10f) ai.ChangeState(new ChaseState());
    }
    public void Exit(EnemyAI ai) { /* detener animacion idle */ }
}

// ChaseState.cs
public class ChaseState : IEnemyState
{
    public void Enter(EnemyAI ai) { /* iniciar animacion de correr */ }
    public void Update(EnemyAI ai)
    {
        Vector3 dir = (ai.Player.position - ai.transform.position).normalized;
        ai.transform.position += dir * 4f * Time.deltaTime;
        ai.transform.LookAt(ai.Player);
        float dist = Vector3.Distance(ai.transform.position, ai.Player.position);
        if (dist < 2f)    ai.ChangeState(new AttackState());
        else if (dist > 15f) ai.ChangeState(new IdleState());
    }
    public void Exit(EnemyAI ai) { }
}

