// ICommand.cs — contrato para todas las acciones reversibles
public interface ICommand
{
    void Execute();
    void Undo();
}

// MoveCommand.cs
using UnityEngine;

public class MoveCommand : ICommand
{
    private readonly Piece     _piece;
    private readonly Vector2Int _from;
    private readonly Vector2Int _to;

    public MoveCommand(Piece piece, Vector2Int destination)
    {
        _piece = piece;
        _from  = piece.Position; // guardamos solo el dato anterior
        _to    = destination;
    }

    public void Execute()
    {
        _piece.Position = _to;
        _piece.UpdateVisual();
    }

    public void Undo()
    {
        _piece.Position = _from;
        _piece.UpdateVisual();
    }
}

// RotateCommand.cs
public class RotateCommand : ICommand
{
    private readonly Piece _piece;
    private readonly int   _degrees;

    public RotateCommand(Piece piece, int degrees)
    {
        _piece   = piece;
        _degrees = degrees;
    }

    public void Execute()
    {
        _piece.Rotation = (_piece.Rotation + _degrees) % 360;
        _piece.UpdateVisual();
    }

    public void Undo()
    {
        _piece.Rotation = (_piece.Rotation - _degrees + 360) % 360;
        _piece.UpdateVisual();
    }
}

// PuzzleManager.cs — orquesta comandos sin conocer su implementacion
using System.Collections.Generic;
using UnityEngine;

public class PuzzleManager : MonoBehaviour
{
    private readonly List<Piece>    _board   = new List<Piece>();
    private readonly Stack<ICommand> _history = new Stack<ICommand>();

    private void ExecuteCommand(ICommand cmd)
    {
        cmd.Execute();
        _history.Push(cmd);
    }

    public void MovePiece(Piece piece, Vector2Int destination)
        => ExecuteCommand(new MoveCommand(piece, destination));

    public void RotatePiece(Piece piece, int degrees)
        => ExecuteCommand(new RotateCommand(piece, degrees));

    // Undo real: O(1), sin copiar el tablero
    public void Undo()
    {
        if (_history.Count == 0) return;
        _history.Pop().Undo();
    }

    // Bonus: Redo con segundo stack
    // private readonly Stack<ICommand> _redoStack = new Stack<ICommand>();
}

