public class ProjectileFactory : MonoBehaviour
{
    [SerializeField] private List<ProjectileEntry> _entries;

    private Dictionary<string, ProjectileEntry> _registry;

    private void Awake()
    {
        _registry = new Dictionary<string, ProjectileEntry>(_entries.Count);
        foreach (var entry in _entries)
            _registry[entry.key] = entry;
    }

    // Registrar un tipo en runtime (p. ej. DLC o mod)
    public void Register(ProjectileEntry entry)
    {
        _registry[entry.key] = entry;
    }

    public GameObject Create(string type, Vector3 position, Quaternion rotation)
    {
        if (!_registry.TryGetValue(type, out var entry))
        {
            Debug.LogError($"Tipo de proyectil no registrado: {type}");
            return null;
        }

        // Aqui se puede usar un pool en lugar de Instantiate
        var obj = Instantiate(entry.prefab, position, rotation);
        if (obj.TryGetComponent<Projectile>(out var proj))
            proj.Init(entry.damage, entry.speed);
        return obj;
    }

