// StatModifier.cs — representa un modificador individual
using System;

public enum ModifierType { Flat, Percent }

public class StatModifier
{
    public readonly string       Source;     // quien aplico el buff
    public readonly float        Value;
    public readonly ModifierType Type;

    public StatModifier(string source, float value, ModifierType type)
    {
        Source = source;
        Value  = value;
        Type   = type;
    }
}

// CharacterStat.cs — stat inmutable con modificadores acumulables
using System.Collections.Generic;
using System.Linq;

public class CharacterStat
{
    private readonly float        _baseValue;
    private readonly List<StatModifier> _modifiers = new List<StatModifier>();

    public CharacterStat(float baseValue) => _baseValue = baseValue;

    // El valor final SIEMPRE se recalcula desde el base
    public float FinalValue
    {
        get
        {
            float flat    = _modifiers.Where(m => m.Type == ModifierType.Flat).Sum(m => m.Value);
            float percent = _modifiers.Where(m => m.Type == ModifierType.Percent).Sum(m => m.Value);
            return (_baseValue + flat) * (1f + percent);
        }
    }

    public void AddModifier(StatModifier mod) => _modifiers.Add(mod);

    // Remover por source — funciona sin importar el orden
    public void RemoveModifiersFromSource(string source)
        => _modifiers.RemoveAll(m => m.Source == source);
}

// PlayerStats.cs — usa CharacterStat en lugar de floats mutables
