public class SaveSystem : MonoBehaviour
{
    // Referencia directa a TODOS los sistemas — acoplamiento maximo
    [SerializeField] private PlayerStats   playerStats;
    [SerializeField] private Inventory     inventory;
    [SerializeField] private QuestLog      questLog;
    [SerializeField] private MapProgress   mapProgress;
    [SerializeField] private GameSettings  settings;
    [SerializeField] private DialogueState dialogueState;
    // Agregar DungeonState requiere modificar Save() y Load()

    public void Save()
    {
        var data = new SaveData
        {
            playerLevel  = playerStats.Level,
            playerHP     = playerStats.CurrentHP,
            items        = inventory.GetAllItems(),
            activeQuests = questLog.GetActiveQuests(),
            visitedRooms = mapProgress.GetVisitedRooms(),
            volume       = settings.MasterVolume,
            lastDialogue = dialogueState.GetLastNodeId()
        };
        File.WriteAllText(SavePath(), JsonUtility.ToJson(data));
    }

    public void Load()
    {
        string json = File.ReadAllText(SavePath());
        var data = JsonUtility.FromJson<SaveData>(json);

        playerStats.Level         = data.playerLevel;
        playerStats.CurrentHP     = data.playerHP;
        inventory.SetItems(data.items);
        questLog.SetQuests(data.activeQuests);
        mapProgress.SetVisited(data.visitedRooms);
        settings.MasterVolume     = data.volume;
        dialogueState.SetNode(data.lastDialogue);
    }

    private string SavePath() =>
        Path.Combine(Application.persistentDataPath, "save.json");
}

