// ISaveable.cs — contrato para cualquier sistema que quiera persistir
public interface ISaveable
{
    string SaveKey      { get; } // identificador unico en el JSON
    object CaptureState();       // devuelve un objeto serializable
    void   RestoreState(object state); // recibe el objeto deserializado
}

