using System.Collections.Generic;
using System.IO;
using UnityEngine;

public class SaveSystem : MonoBehaviour
{
    public static SaveSystem Instance;

    private readonly List<ISaveable> _saveables = new List<ISaveable>();

    private void Awake() => Instance = this;

    // Cada sistema se registra al iniciarse
    public void Register(ISaveable saveable)
        => _saveables.Add(saveable);

    public void Unregister(ISaveable saveable)
        => _saveables.Remove(saveable);

    public void Save()
    {
        var root = new Dictionary<string, string>();
        foreach (var s in _saveables)
            root[s.SaveKey] = JsonUtility.ToJson(s.CaptureState());

        File.WriteAllText(SavePath(), JsonUtility.ToJson(root));
    }

    public void Load()
    {
        if (!File.Exists(SavePath())) return;
        var root = JsonUtility.FromJson<Dictionary<string, string>>(
            File.ReadAllText(SavePath()));

        foreach (var s in _saveables)
        {
            if (root.TryGetValue(s.SaveKey, out var json))
                s.RestoreState(JsonUtility.FromJson(json, s.CaptureState().GetType()));
        }
    }

    private string SavePath() =>
        Path.Combine(Application.persistentDataPath, "save.json");
}

