using UnityEngine;

public class PlayerStats : MonoBehaviour, ISaveable
{
    public string SaveKey => "playerStats";
    public int    Level     = 1;
    public float  CurrentHP = 100f;

    private void Awake()
        => SaveSystem.Instance.Register(this);

    private void OnDestroy()
        => SaveSystem.Instance.Unregister(this);

    [System.Serializable]
    private struct SaveData { public int level; public float hp; }

    public object CaptureState()
        => new SaveData { level = Level, hp = CurrentHP };

    public void RestoreState(object state)
    {
        var data = (SaveData)state;
        Level     = data.level;
        CurrentHP = data.hp;
    }
}

