using System.Collections.Generic;
using UnityEngine;

public class BulletPool : MonoBehaviour
{
    [SerializeField] private Bullet prefab;
    [SerializeField] private int    initialSize = 30;

    private Queue<Bullet> _available = new Queue<Bullet>();

    private void Awake()
    {
        for (int i = 0; i < initialSize; i++)
        {
            Bullet b = Instantiate(prefab);
            b.gameObject.SetActive(false);
            _available.Enqueue(b);
        }
    }

    public Bullet Get(Vector3 pos, Quaternion rot)
    {
        Bullet b = _available.Count > 0
            ? _available.Dequeue()
            : Instantiate(prefab);
        b.transform.SetPositionAndRotation(pos, rot);
        b.gameObject.SetActive(true);
        return b;
    }

    public void Return(Bullet b)
    {
        b.gameObject.SetActive(false);
        _available.Enqueue(b);
    }
}

