// GenericPool.cs — logica de pool escrita UNA SOLA VEZ
using System.Collections.Generic;
using UnityEngine;

public class GenericPool<T> : MonoBehaviour where T : Component
{
    [SerializeField] protected T   prefab;
    [SerializeField] protected int initialSize = 20;

    private readonly Queue<T> _available = new Queue<T>();

    protected virtual void Awake()
    {
        for (int i = 0; i < initialSize; i++)
            _available.Enqueue(CreateInstance());
    }

    private T CreateInstance()
    {
        T obj = Instantiate(prefab, transform); // hijo del pool para orden en jerarquia
        obj.gameObject.SetActive(false);
        return obj;
    }

    public T Get(Vector3 pos = default, Quaternion rot = default)
    {
        T obj = _available.Count > 0 ? _available.Dequeue() : CreateInstance();
        obj.transform.SetPositionAndRotation(pos, rot);
        obj.gameObject.SetActive(true);
        return obj;
    }

    public void Return(T obj)
    {
        obj.gameObject.SetActive(false);
        _available.Enqueue(obj);
    }

    public int AvailableCount => _available.Count;
}

